insert into public.reviews (id, flow, platform, build, screens, figma, languages, reach, story, requested_by, requester_label, reviewer, reviewer_label, status, created_at, started_at, delivered_at, closed_at, page, source, slack) values (
insert into public.findings (id, review_id, code, flow_group, flow, screen, type, lang, sev, description, prod, figma, state, created_label, created_at, updated_at, sort_order, source) values
  ('uxr-audit-2026-10.ONB-01', 'uxr-audit-2026-10', 'ONB-01', 'Launch & onboarding', 'App launch', 'Splash', 'Missing in prod', 'Both', 1, '**Prod:** the Flutter splash is a flat light-mint gradient (~#78F0C0) that fades to white in the bottom ~20% of the screen. It has no brand mark. **Figma:** dark-green to brand-green diagonal gradient with the white bilingual "ولاء بلس / WalaPlus" logo centred. The logo is missing, and the gradient''s colour, direction and darkness are different.', 'en/00-splash', '153:26344', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 1, 'audit'),
  ('uxr-audit-2026-10.ONB-03', 'uxr-audit-2026-10', 'ONB-03', 'Launch & onboarding', 'App launch', 'Notification permission', 'Flow', 'Both', 3, '**Prod:** the Android system dialog "Allow **Walaplus** to send you notifications?" (Allow / Don''t allow) appears straight after the splash on first launch. That is before language selection, with no in-app explanation. **Figma:** notifications are requested through a priming bottom sheet ("Stay updated" / "خلك على اطلاع بكل جديد", 3 benefit bullets, "Turn on notifications" / "Not Now"). The sheet sits at the end of the create-account flow, after the interests step. **Impact:** the sheet does not appear in any production capture. The OS decision is already made at launch, so the designed priming cannot affect it.', 'en/00c', '2218:11686 (AR), 2218:11800 (EN)', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 2, 'audit'),
  ('uxr-audit-2026-10.ONB-04', 'uxr-audit-2026-10', 'ONB-04', 'Launch & onboarding', 'App launch', 'Location permission', 'Flow', 'Both', 3, '**Prod:** the Android location dialog (Precise / Approximate; While using the app / Only this time / Don''t allow) opens on first launch right after the notification dialog. There is no context, and the user has not yet chosen a language or reached anything that needs location. **Figma:** location is requested only through the "allow location access" priming sheet in the Market/Map flow. Production does show that sheet later on the map (ar/56), but only after the OS prompt has already fired. The design''s order (priming, then OS dialog) is reversed.', 'en/00d, en/00e', '4855:24026, 8609:87503 (Market page "allow location access")', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 3, 'audit'),
  ('uxr-audit-2026-10.ONB-07', 'uxr-audit-2026-10', 'ONB-07', 'Launch & onboarding', 'Language selection', 'Language select', 'Flow', 'Both', 3, 'The new experience should set the app language from the device''s language automatically, without asking. Production instead opens with a manual language picker: "Welcome," / "أهلاً بك", "Select Your favorite language" / "اختر اللغة المفضلة لديك", two pill buttons ("English", "العربيـة") and "Start now" / "ابدأ الآن". This adds a step to every first launch that the design removed, and it ignores the device locale. The picker is also weak in itself: the unselected option looks disabled, and there is no WalaPlus logo. Fix: drop this screen and detect the device language on first launch. Keep the language switch in Settings.', 'en/01, ar/01', 'None. By design, Figma has no language step (only the Settings rows 2201:29945 / 153:34806)', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 4, 'audit'),
  ('uxr-audit-2026-10.ONB-09', 'uxr-audit-2026-10', 'ONB-09', 'Launch & onboarding', 'Onboarding', 'Slides 1–3 (content, order, titles and body copy)', 'Flow', 'Both', 3, 'The onboarding flow is totally different from Figma.', 'en/02, en/03, en/04, ar/02, ar/03, ar/04', 'EN 2038:8698, 2038:8952, 2038:9206; AR 153:32011, 340:25167, 2016:20569; welcome copies 7596:63754, 7656:32459, 8576:24891, 8576:19160, 2055:15846, 2090:20271; old 168:9963 / 328:9924', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 5, 'audit'),
  ('uxr-audit-2026-10.AUTH-01', 'uxr-audit-2026-10', 'AUTH-01', 'Login & registration', 'Login', 'Login – mobile / email', 'Layout', 'Both', 3, 'Production stacks everything in the upper two-thirds of the screen: the "Welcome, sign in" heading with "Enter the Mobile number", the input, the primary button, a "Forgot your password?" link, a grey "Login with Email" button and the "Don''t have an account? Register now" footer. Every Figma generation is laid out differently: a header bar (back arrow + Chat pill), a Mobile/Email segmented tab, the title "Enter Your Mobile Number" with an explanatory subtitle, a flag + "+966" field, and the consent text and a full-width "Continue" button pinned to the bottom.', 'en/05, en/07, ar/05, ar/07', '72:21391, 94:12741, 7714:10960, 7714:10867, 8576:20053, 8576:20098, 2090:4614, 2090:9524, 73:16383, 105:8047, 2090:20529, 2090:10486; hidden 168:9244, 168:20099, 328:9326', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 6, 'audit'),
  ('uxr-audit-2026-10.AUTH-12', 'uxr-audit-2026-10', 'AUTH-12', 'Login & registration', 'Forgot password', 'Recover password (email / mobile)', 'Flow', 'Both', 3, 'Production has a self-service "Recover the password" flow by email or mobile that sends a code. Figma has nothing like it. In the newest set a forgotten password can only be reset with a new HR activation code (Forget Pass sheet → Activation Code → Create New Pass). The OTP sets have no password at all, only "Forgot PIN?" → Log Out / Reset PIN. The login screen also offers "Forgot your password?" even though it has no password field. Product needs to confirm which recovery model is current.', 'en/05, en/08, en/09, ar/08, ar/09', '7596:64470, 8576:26631 (Forget Pass sheet); 7596:64565, 8576:27117 (Activation Code 3); 7596:64973, 8576:27467 (Create New Pass 3); 7596:63023, 8576:24838 (Forgot PIN sheet); 7596:64066, 8576:26282 (Mail & Pass)', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 7, 'audit'),
  ('uxr-audit-2026-10.AUTH-15', 'uxr-audit-2026-10', 'AUTH-15', 'Login & registration', 'Registration', 'End-to-end flow', 'Flow', 'Both', 3, 'Production: "Register now" → Choose Company → one long form → Register. Newest Figma: the same entry screen as login ("Let''s get to know your company by your mobile number") → 6-character HR activation code → "Is this your information?" HR-record card → create password → PIN → biometric → welcome. OTP-generation Figma: mobile/email OTP → Build account (1/4) → PIN (2/4) → biometric (3/4) → interests (4/4) → notifications priming → Home. Production matches neither. In Figma the login entry also handles new users, so there is no separate "Register now" path.', 'en/05, en/10, en/11, en/12, ar/10, ar/11, ar/12', 'Newest: 7714:10960, 8576:20053, 7582:9386, 8576:20787, 7582:58748, 8576:21383, 7592:61061, 8576:22035, 7596:62156; OTP: 73:16383, 73:16173, 79:9913, 2090:10486, 2090:10535, 2090:13242; hidden: 193:11359, 193:12422', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 8, 'audit'),
  ('uxr-audit-2026-10.AUTH-24', 'uxr-audit-2026-10', 'AUTH-24', 'Login & registration', 'Registration', 'Terms & Conditions link', 'State', 'EN', 3, '"the terms and conditions" opens a solid green screen that never loads (waited 20 s+); Back is the only way out. The Terms page does load from Settings (ar/86), so only this link is broken.', 'en/12, en/14', '72:21391, 8576:20053, 7582:58748 (consent links)', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 9, 'audit'),
  ('uxr-audit-2026-10.AUTH-30', 'uxr-audit-2026-10', 'AUTH-30', 'Login & registration', 'Login – email OTP / change PIN', 'Back control', 'Visual', 'AR', 2, 'The back control is a thin chevron ">"; Figma uses an arrow "→". The production pre-login screens also use "→", so back controls differ across one flow.', 'ar/15, ar/88', '94:12872, 153:35707, 2016:21861', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 10, 'audit'),
  ('uxr-audit-2026-10.AUTH-34', 'uxr-audit-2026-10', 'AUTH-34', 'Login & registration', 'Change PIN', 'Phone number text direction', 'RTL/LTR', 'AR', 2, 'The phone number text direction is wrong. In Arabic the masked number follows the RTL paragraph direction, so it renders scrambled ("+966 5 ••••• 889•"). It should be its own LTR run, as in Figma ("+96660550225" in 2016:21861, "+9666*****25" in 72:21627).', 'ar/88', '2016:21861, 72:21627', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 11, 'audit'),
  ('uxr-audit-2026-10.AUTH-38', 'uxr-audit-2026-10', 'AUTH-38', 'Login & registration', 'PIN lock on resume', 'Chat button', 'Missing in prod', 'EN', 3, 'Chat button is missing. Figma''s PIN Code - Login screen has a "Chat" button in the top-right header. Production''s PIN lock has no header and no chat entry, so a user who is locked out or has forgotten the PIN cannot reach support from this screen.', 'en/95', '8576:24340, 2224:23169', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 12, 'audit'),
  ('uxr-audit-2026-10.HOME-01', 'uxr-audit-2026-10', 'HOME-01', 'Home & notifications', 'Home', 'Header', 'Missing in prod', 'Both', 3, 'Every Figma generation shows a points-balance pill (EN "[SAR sign] 5,000", AR "0 [SAR sign]") next to the notification bell. In production the header has only the greeting ("Hala, abdulrahman" / "هلا، abdulrahman") and the bell. The user''s points balance does not appear anywhere on Home.', 'ar/20, en/20', '6035:24374, 6044:25692, 6505:41019, 5612:40632', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 13, 'audit'),
  ('uxr-audit-2026-10.HOME-08', 'uxr-audit-2026-10', 'HOME-08', 'Home & notifications', 'Home', 'Body sections · card component', 'Component', 'Both', 3, 'The UI of the card component is different in the Home body sections. Production''s offer and brand cards do not match the card component in the Figma body sections (Gen C).', 'ar/20–24, en/20–24', '6035:24546, 6044:25864, 6505:41191', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 14, 'audit'),
  ('uxr-audit-2026-10.HOME-11', 'uxr-audit-2026-10', 'HOME-11', 'Home & notifications', 'Home', 'Section-title wording', 'Copy', 'Both', 2, 'AR "العروض المطاعم الجديدة" has a doubled definite article; it should be "عروض المطاعم الجديدة". EN "New Restaurant''s offers" has a wrong apostrophe and casing. The photo-tile caption "قهاوي تعدل مذاجك" misspells "مزاجك".', 'ar/22–23, en/22', '—', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 15, 'audit'),
  ('uxr-audit-2026-10.HOME-12', 'uxr-audit-2026-10', 'HOME-12', 'Home & notifications', 'Home', 'Content localization', 'Copy', 'EN', 3, 'In the EN UI, CMS content stays in Arabic: <br>• the hero banner (Hertz creative with Arabic copy only); <br>• the Happy Tuesday caption "ثلاثاء السعد"; <br>• the photo-tile captions (وجبات سريعة، قهاوي تعدل مذاجك، العناية الشخصية والعطور، تسوق أونلاين ووفّر). <br>Figma EN frames use EN content throughout.', 'en/20–24', '6035:24374', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 16, 'audit'),
  ('uxr-audit-2026-10.HOME-13', 'uxr-audit-2026-10', 'HOME-13', 'Home & notifications', 'Home', 'Food & Coffee photo tile', 'Data', 'Both', 3, 'The third "Food & Coffee" photo tile shows a wine glass next to a steak plate. This imagery is inappropriate for a KSA audience and a corporate benefits app.', 'en/22–23 (cropped in ar/22–23)', '—', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 17, 'audit'),
  ('uxr-audit-2026-10.HOME-14', 'uxr-audit-2026-10', 'HOME-14', 'Home & notifications', 'Home', 'Voucher and offer cards: content', 'Data', 'Both', 3, 'The gaming voucher cards ("شحن سوا", "شحن فري فاير" / "Sawa", "Free Fire") have blank logo placeholders and the price "يبدأ من 0" / "starts from 0". Figma shows real logos and "starts from 200". "Exclusive Offers" shows "سميراميس مصر" / "Semiramis Egypt" with a blank logo, and a Doha hotel, to a KSA account.', 'ar/23–24, en/23–24', '6035:24961, 6035:24780', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 18, 'audit'),
  ('uxr-audit-2026-10.HOME-15', 'uxr-audit-2026-10', 'HOME-15', 'Home & notifications', 'Home', 'Long names in cards', 'Visual', 'Both', 3, 'Long brand names and captions shrink to a tiny, near-unreadable size instead of wrapping or truncating. Examples: "Alrayyan Hotel Doha, Curio Collection by Hilton" in Exclusive Offers; the 4th "New Merchants" card; the "العناية الشخصية والعطور" caption; and "بترومين اكسبريس" / "حلويات سعد الدين" in the brand row. Text size therefore varies between cards in the same row. Figma cards use one fixed name style.', 'ar/21–24, en/21–24', '6035:24546', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 19, 'audit'),
  ('uxr-audit-2026-10.HOME-20', 'uxr-audit-2026-10', 'HOME-20', 'Home & notifications', 'Special offers', 'App bar', 'Missing in Figma', 'EN', 2, 'The header illustration in the English version shall be changed in production.', 'ar/90, en/90', '3906:39593, 5120:22643', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 20, 'audit'),
  ('uxr-audit-2026-10.HOME-21', 'uxr-audit-2026-10', 'HOME-21', 'Home & notifications', 'Special offers', 'Brand card', 'Data', 'Both', 2, 'The logo is an empty grey circle, where Figma has a rounded-square brand logo. The card text is test data, "shahbndr / ham alnam" (AR "شهبندر / هم النم"). Figma shows the brand name plus an offer description ("Get 25% discount on total invoice"). The 2-column grid and banner match.', 'ar/90, en/90', '3906:39593, 5120:22643', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 21, 'audit'),
  ('uxr-audit-2026-10.HOME-22', 'uxr-audit-2026-10', 'HOME-22', 'Home & notifications', 'Company offer store', 'Cover and logo', 'Data', 'Both', 2, 'The production cover is an empty grey gradient and the brand logo an empty placeholder. Figma shows a full-bleed brand photo with the brand logo.', 'ar/91, en/91', '3906:40042, 5120:22979', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 22, 'audit'),
  ('uxr-audit-2026-10.HOME-23', 'uxr-audit-2026-10', 'HOME-23', 'Home & notifications', 'Company offer store', 'Back button', 'Component', 'Both', 2, 'Back is a chevron in a white circle ("<" in EN, ">" in AR). Figma uses an arrow in a circle ("←" / "→"), and other production stores (e.g. 48/49) also use the arrow.', 'ar/91, en/91', '3906:40042, 5120:22979', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 23, 'audit'),
  ('uxr-audit-2026-10.HOME-24', 'uxr-audit-2026-10', 'HOME-24', 'Home & notifications', 'Company offer store', 'Share action', 'Missing in prod', 'Both', 2, 'The Figma share button (top-right in EN, top-left in AR) is absent.', 'ar/91, en/91', '3906:40042, 5120:22979', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 24, 'audit'),
  ('uxr-audit-2026-10.HOME-25', 'uxr-audit-2026-10', 'HOME-25', 'Home & notifications', 'Company offer store', 'Brand category', 'Copy', 'Both', 2, 'The category shows the raw lowercase English slug "restaurants" in both languages. Figma has "Food & Drink" / "أكل ومشروبات".', 'ar/91, en/91', '3906:40042, 5120:22979', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 25, 'audit'),
  ('uxr-audit-2026-10.HOME-27', 'uxr-audit-2026-10', 'HOME-27', 'Home & notifications', 'Company offer store', 'Offer item', 'Component', 'Both', 2, 'In production each offer is a small pill chip with only the title ("ham alnam" / "هم النم"). Figma uses a full-width card with title, description, and "Valid until 31 December 2026" with a clock icon (AR "صالح حتى 31 ديسمبر 2026"). The user cannot see the offer description or validity on the store page.', 'ar/91, en/91', '3906:40042, 5120:22979', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 26, 'audit'),
  ('uxr-audit-2026-10.MKT-04', 'uxr-audit-2026-10', 'MKT-04', 'Market', 'Market tab', 'Category chips and filter chips', 'Visual', 'Both', 2, 'Production uses full category names under the chip icons, and they are cut off: "الأطعمة..", "الأزياء والـ", "الجمال والـ", "الرعاية الص", "Food & ...", "Fashion ...", "Beauty ...", "Health C...". Figma uses short labels that fit ("الكل، زد، العاب؟، مطاعم، أزياء" / "All, Zed, Games, Food, Fashion"). The filter chip "نقاط مكتسـ" is also cut off at the screen edge.', 'ar/40, ar/47, en/40, en/41, en/47', '2389:70072, 5066:11354, 5146:40509, 5154:22661', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 27, 'audit'),
  ('uxr-audit-2026-10.MKT-05', 'uxr-audit-2026-10', 'MKT-05', 'Market', 'Market tab', 'Voucher card (list and search results)', 'Component', 'Both', 2, 'Figma voucher cards include online and in-store channel icons, a discount badge ("خصم 10%" / "10% Discount"), the logo in a rounded tile, and a "تبدأ من" / "Start from" prefix. Production voucher cards show only a bare logo, the name and "من 300" / "From 300". They have no channel icons, even though production offer cards do show them.', 'ar/40, ar/41, en/40, en/41, ar/55', '2389:70378, 7631:24636, 2987:28956', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 28, 'audit'),
  ('uxr-audit-2026-10.MKT-06', 'uxr-audit-2026-10', 'MKT-06', 'Market', 'Market tab', 'Voucher card', 'Visual', 'Both', 3, 'Long brand names break the grid. "بيت عبد الغني الكبير للذهب والمجوهرات" wraps to 2 lines, and "AbdulGhani The Great House for Gold and Jew…" is cut off. Cards in the same row end up with uneven text and the price row is pushed down. Figma uses short single-line names. Long names shall be truncated.', 'ar/41, en/40', '2389:70378, 7631:24636', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 29, 'audit'),
  ('uxr-audit-2026-10.MKT-08', 'uxr-audit-2026-10', 'MKT-08', 'Market', 'Market tab', 'Offer card', 'Layout', 'Both', 3, 'Production offer cards are about 120 px tall with an empty lower half, and the logo has no tile. Long titles are cut off in one line ("سلام | إنترنت سريع وباقات جوال و."). Figma offer cards are compact: logo tile, name, then a discount badge and an "كسب نقاط" / "Earn Points" badge on one row.', 'ar/47, en/47, en/47b', '5066:11354, 4661:16984, 5154:22661', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 30, 'audit'),
  ('uxr-audit-2026-10.MKT-09', 'uxr-audit-2026-10', 'MKT-09', 'Market', 'Market tab', 'Filter sheet', 'Copy', 'AR', 2, 'The filter sheet is totally different from Figma. Title reads "فلترة التصنيفات" but Figma has "تصفية التصنيفات". Buttons read "فلترها" / "إزالة" but Figma has "تطبيق الفلاتر" / "مسح الكل".', 'ar/51', '2389:78339, 2389:78383', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 31, 'audit'),
  ('uxr-audit-2026-10.MKT-10', 'uxr-audit-2026-10', 'MKT-10', 'Market', 'Market tab', 'Filter sheet', 'RTL/LTR', 'AR', 3, 'Element placement differs from Figma in RTL. In Figma the checkbox sits at the right next to the label, the chevron is at the far left, and the title is right-aligned. In production the chevron sits next to the label, the checkbox is at the far left, and the title is centred under a drag handle. Button order is also swapped: Figma has the primary "تطبيق الفلاتر" on the left and "مسح الكل" on the right; production has the primary "فلترها" on the right and "إزالة" on the left.', 'ar/51', '2389:78339', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 32, 'audit'),
  ('uxr-audit-2026-10.MKT-11', 'uxr-audit-2026-10', 'MKT-11', 'Market', 'Market tab', 'Filter sheet', 'State', 'AR', 3, 'With no category ticked, the primary "فلترها" button is enabled (solid green). Figma shows "تطبيق الفلاتر" disabled (grey) until something is selected.', 'ar/51', '2389:78339', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 33, 'audit'),
  ('uxr-audit-2026-10.MKT-12', 'uxr-audit-2026-10', 'MKT-12', 'Market', 'Market tab', 'Filter and sort sheets', 'Layout', 'AR', 3, 'The sheets open above the bottom navigation. The nav bar and the centre QR button stay visible and are not dimmed under the scrim. The Figma sheets are standalone overlays at the bottom of the screen with no nav bar.', 'ar/51, ar/52', '2389:78339, 2389:78450', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 34, 'audit'),
  ('uxr-audit-2026-10.MKT-13', 'uxr-audit-2026-10', 'MKT-13', 'Market', 'Market tab', 'Sort sheet', 'Copy', 'AR', 2, 'Production reads "رتبها" / "هات الجديد" / "القديم" with button "رتبها" (repeats the title and mixes dialect with MSA). Figma has "الترتيب" / "الأحدث أولًا" / "الأقدم أولًا" with button "تطبيق". The title is centred in production and right-aligned in Figma.', 'ar/52', '2389:78450, 2389:78470', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 35, 'audit'),
  ('uxr-audit-2026-10.MKT-14', 'uxr-audit-2026-10', 'MKT-14', 'Market', 'Market tab', 'Sort sheet', 'State', 'AR', 2, 'No sort option is pre-selected, so both radios are empty. Figma shows the current sort selected (filled radio).', 'ar/52', '2389:78450, 2389:78470', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 36, 'audit'),
  ('uxr-audit-2026-10.MKT-15', 'uxr-audit-2026-10', 'MKT-15', 'Market', 'Voucher / offer store', 'Store header', 'Visual', 'Both', 2, 'The cover image is empty (white-grey gradient only) on the voucher stores (Keemart AR, Dunkin EN) and on the AR Hertz offer store. The EN Hertz store does load its cover. Figma shows a full-bleed brand photo behind the header buttons.', 'ar/42, en/42, ar/48, en/48', '2389:71457, 5146:43047, 4661:16252, 5154:26803', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 37, 'audit'),
  ('uxr-audit-2026-10.MKT-16', 'uxr-audit-2026-10', 'MKT-16', 'Market', 'Voucher / offer store', 'Store header', 'Missing in prod', 'Both', 3, 'There is no Share button. Figma has Share plus Favourite next to Back; production has only Favourite.', 'ar/42, en/42, ar/48, en/48, en/49', '2389:71457, 5146:43047, 4661:16252, 5154:26803', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 38, 'audit'),
  ('uxr-audit-2026-10.MKT-17', 'uxr-audit-2026-10', 'MKT-17', 'Market', 'Voucher store', 'Store details', 'Copy', 'Both', 2, 'AR reads "اختر القسيمة اللي تبيها" and "كيف تستخدمها؟"; Figma has "اختر القسيمة المناسبة لك" and "طريقة استخدام القسيمة". EN reads "Choose the voucher you want" and "How to use?"; Figma has "Choose the voucher" and "How do you use it?".', 'ar/42, en/42', '2389:71457, 5146:43047', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 39, 'audit'),
  ('uxr-audit-2026-10.MKT-18', 'uxr-audit-2026-10', 'MKT-18', 'Market', 'Voucher store', 'Voucher rows', 'Copy', 'Both', 2, 'Values are written with the word "ريال" ("قسيمة شرائية بقيمة 30 ريال") or "AED" ("Voucher by 10 AED"). Figma uses the new Saudi riyal sign ("قسيمة شرائية بقيمة 100 [SAR sign]", "[SAR sign] 100 Voucher"). Production offers already use that sign ("خصم 20 [SAR sign]"), so currency display is inconsistent inside the app.', 'ar/42, ar/46, en/42', '2389:71457, 5146:43047', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 40, 'audit'),
  ('uxr-audit-2026-10.MKT-19', 'uxr-audit-2026-10', 'MKT-19', 'Market', 'Voucher / offer store', 'Store details (bottom)', 'Missing in prod', 'Both', 3, 'The "متاجر مشابهة" / "Similar Stores" carousel at the end of the store page is missing. Production ends after the last voucher row (ar/43) or the last offer card (en/49, followed by empty space).', 'ar/43, en/49', '2389:71593, 5146:42810, 4661:16252, 5154:26803', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 41, 'audit'),
  ('uxr-audit-2026-10.MKT-21', 'uxr-audit-2026-10', 'MKT-21', 'Market', 'Voucher store', 'Voucher selected (bottom bar)', 'Copy', 'AR', 2, 'Buttons read "بشتريها" / "برسلها هدية" (first person, "I''ll buy it" / "I''ll send it as a gift"). Figma has "اشترِ الآن" / "أرسلها هدية" (EN Figma: "Buy it" / "Send as gift").', 'ar/46', '2389:71457, 5146:43047', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 42, 'audit'),
  ('uxr-audit-2026-10.MKT-22', 'uxr-audit-2026-10', 'MKT-22', 'Market', 'Voucher store', 'Voucher selected (bottom bar)', 'RTL/LTR', 'AR', 2, 'In AR production the primary green "بشتريها" is on the left and "برسلها هدية" is on the right. Figma AR puts the primary "اشترِ الآن" on the right (the leading side), mirroring EN, where "Buy it" is on the left.', 'ar/46', '2389:71457, 5146:43047', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 43, 'audit'),
  ('uxr-audit-2026-10.MKT-23', 'uxr-audit-2026-10', 'MKT-23', 'Market', 'Voucher store', 'How-to-use sheet', 'Component', 'Both', 2, 'Production shows one bordered block holding the merchant''s whole legal text: terms mixed into the steps, a reference to the Keeta app, a raw non-tappable URL "https://dunkin.ae/locations/", and repeated words ("UAE stores only Only 1 (one)"). Figma has a numbered 3-step card plus a separate "الشروط والأحكام" / "Terms & Conditions" card.', 'ar/44, en/44', '2389:71162, 5146:41949', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 44, 'audit'),
  ('uxr-audit-2026-10.MKT-25', 'uxr-audit-2026-10', 'MKT-25', 'Market', 'Voucher store', 'About-brand sheet', 'Copy', 'AR', 2, 'Section heading reads "بيانات التواصل"; Figma has "تواصل مع فريق ولاء بلس". The row reads "أرسل لنا وبنضبطك / يتم الرد عليك في أقرب وقت"; Figma has "الدعم والمساعدة / تواصل معنا، وسنرد عليك في أقرب وقت.". The production AR text looks like a literal translation of the EN Figma copy ("Send a message and we will fix it").', 'ar/45', '9251:18884, 2389:71891, 2389:71981', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 45, 'audit'),
  ('uxr-audit-2026-10.MKT-28', 'uxr-audit-2026-10', 'MKT-28', 'Market', 'Offer store / activation', 'Validity and expiry dates', 'Visual', 'AR', 2, 'Dates use Eastern Arabic digits ("صالح حتى ١٢ أكتوبر ٢٠٣٤", "٨ مايو ٢٠٤١", "ينتهي في ٨ مايو"), while every other number on the same screen uses Western digits. Figma uses Western digits ("صالح حتى 31 ديسمبر 2026", "31 ديسمبر").', 'ar/48, ar/49, ar/50', '4661:16252, 7064:17367', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 46, 'audit'),
  ('uxr-audit-2026-10.MKT-29', 'uxr-audit-2026-10', 'MKT-29', 'Market', 'Offer store', 'Offer card', 'Component', 'Both', 3, 'Every free offer has a green footer reading "مجاني" / "Free". In Figma, the green footer appears only on paid offers, where it shows the points price ("100"). Production also drops the usage chips that Figma shows ("يمكن استخدام العرض 3 مرات", "∞", "3x Usage").', 'ar/48, en/48, en/49', '4661:16252, 5154:26803', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 47, 'audit'),
  ('uxr-audit-2026-10.MKT-30', 'uxr-audit-2026-10', 'MKT-30', 'Market', 'Offer store', 'Offer card', 'Data', 'Both', 3, 'The Hertz offers are valid until "12 October 2034" and "8 May 2041" (implausible), and the 3rd and 4th offers repeat the title as their description. Figma uses realistic validity ("31 December 2026") and distinct descriptions.', 'ar/48, en/48', '4661:16252, 5154:26803', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 48, 'audit'),
  ('uxr-audit-2026-10.MKT-31', 'uxr-audit-2026-10', 'MKT-31', 'Market', 'Offer activation', 'Activate offer', 'Data', 'AR', 3, 'The "كيف تستخدم العرض؟" and "الشروط والأحكام" boxes contain only "1.1" and "2.1", which look like placeholder content. Figma shows 3 numbered steps and 3 numbered conditions.', 'ar/50', '7064:17367, 7064:18003', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 49, 'audit'),
  ('uxr-audit-2026-10.MKT-33', 'uxr-audit-2026-10', 'MKT-33', 'Market', 'Offer activation', 'Activate offer', 'Visual', 'AR', 2, 'The store-link row uses an upload/share glyph (arrow up out of a tray). Figma uses an external-link icon (arrow out of a box).', 'ar/50', '7064:17367', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 50, 'audit'),
  ('uxr-audit-2026-10.MKT-34', 'uxr-audit-2026-10', 'MKT-34', 'Market', 'Search', 'Search before typing', 'Missing in prod', 'AR', 3, 'Production shows the tabs on an otherwise blank white page. Figma shows "عمليات البحث السابقة" (recent-search chips with "مسح الكل"), "الأكثر بحثًا" (popular-search chips) and "التصنيفات الأكثر بحثًا 🔥" (recommended store cards).', 'ar/53', '2987:15361, 8609:91917', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 51, 'audit'),
  ('uxr-audit-2026-10.MKT-35', 'uxr-audit-2026-10', 'MKT-35', 'Market', 'Search', 'Typing', 'Missing in prod', 'AR', 3, 'There are no live suggestions. Results appear only after pressing Enter on the keyboard, with no hint that this is needed. Figma shows an autocomplete list while typing, with history items (clock icon) and suggested terms ("قهوة عربية", "قهوة فرنسية"…).', 'ar/53, ar/54', '2987:28275, 8609:94094', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 52, 'audit'),
  ('uxr-audit-2026-10.MKT-36', 'uxr-audit-2026-10', 'MKT-36', 'Market', 'Search', 'Results', 'Copy', 'Both', 2, 'AR heading reads "كل نتائج البحث على "costa"" (preposition "على", straight quotes, plain text). Figma has "نتائج البحث عن «قهوة»" (preposition "عن", guillemets, query in green). EN reads "All results for "costa""; Figma has "All search results for "Coffee"".', 'ar/54, ar/55, ar/96, en/54', '2987:29109, 2987:28956, 8620:94721, 8620:94384', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 53, 'audit'),
  ('uxr-audit-2026-10.MKT-37', 'uxr-audit-2026-10', 'MKT-37', 'Market', 'Search', 'Results relevance', 'Data', 'Both', 3, 'Searching "costa" opens on the Offers tab (24 results); every result visible in the capture (the first 5) is unrelated (York Towers, Tamam Recruitment Office, Sand Spa, Hakeem Oyoun, Zakiopticals…). The only relevant hit, the "كوستا الإمارات" voucher, is in the second tab. Searching "pizza" is mostly relevant but includes "مركز ووش | المتعة للجميع". Figma results contain only brands that match the query.', 'ar/54, ar/55, en/54, ar/96', '2987:29109, 2987:28956, 8620:94721', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 54, 'audit'),
  ('uxr-audit-2026-10.MKT-38', 'uxr-audit-2026-10', 'MKT-38', 'Market', 'Search', 'Results', 'Data', 'AR', 1, 'Several results have a blank grey logo tile: "كوستا الإمارات" (the only relevant voucher), "مكتب تمام للاستقدام", "مركز ووش", "بيراتا بيتزاريا". Every Figma result has a logo.', 'ar/54, ar/55, ar/96', '2987:28956, 2987:29109', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 55, 'audit'),
  ('uxr-audit-2026-10.MKT-40', 'uxr-audit-2026-10', 'MKT-40', 'Market', 'Map', 'Location priming sheet', 'Copy', 'AR', 1, 'Production reads "تفعيل الوصول لمكانك" / "قم بإعطاء صلاحية الوصول لمكانك حتى نتمكن من عرض المتاجر القريبة منك" / "فعل تحديد المكان" / "إستكمال بدون تفعيل" (hamza error). Figma has "فعّل الوصول إلى موقعك" / "اسمح بالوصول إلى موقعك لعرض المتاجر والعروض القريبة منك." / "تفعيل الموقع" / "المتابعة دون تفعيل".', 'ar/56', '4855:24026, 8609:87503', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 56, 'audit'),
  ('uxr-audit-2026-10.MKT-41', 'uxr-audit-2026-10', 'MKT-41', 'Market', 'Map', 'After declining location', 'Flow', 'AR', 3, 'After the user taps "إستكمال بدون تفعيل", the app still triggers Google''s Location Accuracy system dialog. In Figma, declining leads to the map with an in-map "فعّل الموقع… / تفعيل الموقع" banner and no system prompt.', 'ar/57', '4855:24026, 4855:15127', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 57, 'audit'),
  ('uxr-audit-2026-10.MKT-42', 'uxr-audit-2026-10', 'MKT-42', 'Market', 'Map', 'Map loading', 'Missing in Figma', 'AR', 2, 'For several seconds the map is a blank beige canvas with a "جارِ التحديث" pill. Neither map section has a loading state. The location-activation banner also differs: production shows a yellow banner with a pin icon, "لتحسين تجربتك، فعّل الوصول للموقع", and a green text link "فعل تحديد المكان"; Figma (4855:15127) shows a peach/red banner with a warning icon, "فعّل الموقع لعرض المتاجر القريبة منك.", and a white pill button "تفعيل الموقع".', 'ar/58', '2987:12880 section, 4855:15127, 8609:78522 section', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 58, 'audit'),
  ('uxr-audit-2026-10.MKT-44', 'uxr-audit-2026-10', 'MKT-44', 'Market', 'Map', 'Location banner', 'Visual', 'AR', 1, 'Production shows a yellow banner with a pin icon, "لتحسين تجربتك، فعّل الوصول للموقع", and a green text link "فعل تحديد المكان". Figma shows a peach/red banner with a warning icon, "فعّل الموقع لعرض المتاجر القريبة منك.", and a white pill button "تفعيل الموقع".', 'ar/57, ar/58', '4855:15127, 8609:87169', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 59, 'audit'),
  ('uxr-audit-2026-10.MKT-45', 'uxr-audit-2026-10', 'MKT-45', 'Market', 'Map', 'Map controls', 'Component', 'AR', 1, 'Production shows Google zoom +/- buttons at bottom-left plus a recentre button at bottom-right (ar/59). Figma has no zoom controls; it has the recentre button plus a WalaPlus "W" floating button, which is missing in production.', 'ar/58, ar/59', '4855:15127, 2987:13186', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 60, 'audit'),
  ('uxr-audit-2026-10.MKT-46', 'uxr-audit-2026-10', 'MKT-46', 'Market', 'Coupons', 'Coupons tab and flow', 'Missing in prod', 'Both', 1, 'The whole Coupons flow is absent from production: the "الكوبونات" Market tab, image-led coupon cards ("حتى 60%", struck-through price), coupon store "الكوبونات المتاحة (10)", purchase coupon, summary, success and transaction details. Production Market has only Offers and Vouchers. This may be an unreleased feature; confirm the roadmap.', 'ar/40, ar/47, en/40, en/47', '8934:5815, 8996:27441, 6597:44671, 6605:42057, 8934:6241', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 61, 'audit'),
  ('uxr-audit-2026-10.MKT-58', 'uxr-audit-2026-10', 'MKT-58', 'Market', 'Home category → Market', 'Market chips', 'Visual', 'AR', 2, 'Category chip labels are truncated ("الأزياء والـ", "الجمال والـ", "الرعاية الص"). Figma uses short one-word chip labels (مطاعم، أزياء).', 'ar/92', '6505:43589, 5066:11354', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 62, 'audit'),
  ('uxr-audit-2026-10.WAL-01', 'uxr-audit-2026-10', 'WAL-01', 'Wallet', 'Wallet', 'Balance card: action buttons', 'Copy', 'Both', 1, '**Figma AR:** "شحن النقاط / استبدال النقاط / تحويل النقاط". **Prod AR:** "اشحن نقاطك / استبدل نقاطك / حول نقاطك". **Figma EN:** "Top up / Redeem / Convert". **Prod EN:** "Top up your points / Redeem your points / Transfer your points", and every EN label wraps to two lines. The Figma EN label "Convert" contradicts AR "تحويل" and the "Points transfer" page, so prod''s "Transfer" is the more accurate word. The Figma EN label should be updated.', 'ar/60, ar/61, en/60, en/61', '4195:32126, 4195:32895, 3196:35698, 8576:33799, 8576:34522', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 63, 'audit'),
  ('uxr-audit-2026-10.WAL-02', 'uxr-audit-2026-10', 'WAL-02', 'Wallet', 'Wallet', 'Balance card: amount row', 'RTL/LTR', 'EN', 1, '**EN prod:** the number comes before the WalaPlus coin icon ("0 ◉"). **EN Figma:** every frame puts the icon first ("◉ 0", "◉ 500,000"). AR prod matches Figma (icon left, number right). The app mirrors this row in LTR; the design does not.', 'en/60, en/61', '8576:33799, 8576:34522, 8585:47345', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 64, 'audit'),
  ('uxr-audit-2026-10.WAL-03', 'uxr-audit-2026-10', 'WAL-03', 'Wallet', 'Wallet', 'Card below the balance', 'Missing in Figma', 'Both', 1, '**Prod:** a "قريباً / Coming soon" teaser ("ادفع مثل كل مرة، وخذ أكثر كل مرة" / "Pay like every time, & take more every time."). It has a purple card-and-coins illustration and no CTA. **Figma:** no Wallet-page frame has this teaser. Figma shows either the card-link promo "اربط بطاقتك واكسب نقاطًا مع كل عملية شراء" (3 bullets, "اربط بطاقتك الآن" / "Link it now" CTA) or the "إجمالي الكاش باك / Total Cashback" card. The cashback feature itself is out of scope. Only the placeholder in this slot is undocumented.', 'ar/60, ar/61, en/60, en/61', '4195:32126, 8576:33799 (card-link promo); 3196:35698, 3196:36017, 8585:47345 (Total Cashback card)', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 65, 'audit'),
  ('uxr-audit-2026-10.WAL-04', 'uxr-audit-2026-10', 'WAL-04', 'Wallet', 'Wallet', 'Coming-soon teaser copy', 'Copy', 'Both', 1, '**EN:** "Pay like every time, & take more every time." is ungrammatical. **AR:** uses stretched tatweel in "مـــرة" and puts a space before the comma ("مرة ، وخذ").', 'ar/60, en/60', '— (no Figma frame)', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 66, 'audit'),
  ('uxr-audit-2026-10.WAL-05', 'uxr-audit-2026-10', 'WAL-05', 'Wallet', 'Wallet', 'Tabs', 'Copy', 'Both', 2, '**Figma tab names:** AR "العمليات / مشترياتي", EN "Transaction / My Purchases". **Prod tab names:** AR "العمليات / المشتريات", EN "Operations / Purchases". EN "Operations" is a literal translation of "العمليات". It matches neither Figma nor prod''s own details screen, which says "Transaction Summary".', 'ar/60, ar/61, en/60, en/61', '4195:32126, 4195:32895, 8576:33799, 8576:34522', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 67, 'audit'),
  ('uxr-audit-2026-10.WAL-06', 'uxr-audit-2026-10', 'WAL-06', 'Wallet', 'Wallet', 'Sort and filter chips', 'Copy', 'Both', 1, '**Transactions tab:** Figma AR is "الترتيب / النقاط المكتسبة / نقاط منتهية الصلاحية"; prod AR is "رتبها / نقاط كسبتها / نقاط فقدتها". Figma EN is "Sort / Points gained / Points lost"; prod EN is "Sort / Earned points / Lost points". The AR filter''s meaning changed from "expired points" to "points you lost". **Purchases tab:** the sort chip also reads "رتبها" where Figma has "الترتيب".', 'ar/60, ar/61, en/60', '3196:35382, 3196:35698, 3196:36017 (AR); 8576:33799 (EN)', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 68, 'audit'),
  ('uxr-audit-2026-10.WAL-07', 'uxr-audit-2026-10', 'WAL-07', 'Wallet', 'Wallet', 'Transactions tab, empty state', 'State', 'Both', 1, '**Figma:** the empty state shows only the message under the tabs, with no chips. **Prod:** the Sort, Earned and Lost chips stay visible above "لم تقم بأي عملية حتى الآن.", so sort and filter controls are offered on an empty list.', 'ar/60, en/60', '4195:32126', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 69, 'audit'),
  ('uxr-audit-2026-10.WAL-08', 'uxr-audit-2026-10', 'WAL-08', 'Wallet', 'Wallet', 'Transactions tab, empty-state copy', 'Copy', 'Both', 1, '**AR:** Figma "لا توجد عمليات حتى الآن"; prod "لم تقم بأي عملية حتى الآن.". **EN:** Figma has no empty-state frame for the transactions tab. Prod shows "You haven''t made any transaction yet."', 'ar/60, en/60', '4195:32126', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 70, 'audit'),
  ('uxr-audit-2026-10.WAL-09', 'uxr-audit-2026-10', 'WAL-09', 'Wallet', 'Wallet / My Items', 'Purchase list item content', 'Data', 'Both', 2, '**Figma row:** brand logo, then type plus brand ("عرض من هنقر ستيشن", "قسيمة شراء من مكتبة جرير", "Offer from Hunger Station"), then the time. **Prod row:** logo plus the offer description only ("خصم 20 % على إجمالي الفاتورة"). There is no brand name and nothing says whether the item is an offer or a voucher. Users have to recognise the small logo to know which brand it is.', 'ar/61, en/61, ar/79', '3196:36017 (AR), 8585:47345 (EN), 84:21364, 2200:33446', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 71, 'audit'),
  ('uxr-audit-2026-10.WAL-10', 'uxr-audit-2026-10', 'WAL-10', 'Wallet', 'Wallet', 'Purchase list status badge', 'State', 'Both', 2, '**Figma:** every purchase row has a status badge ("ساري" / "منتهي", "Active" / "Finished"). **Prod Wallet → Purchases:** no badge. The My Items list (ar/79) does show a "صالح" badge on the same two items, so the two prod views of the same data disagree.', 'ar/61, en/61', '3196:36017, 8585:47345', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 72, 'audit'),
  ('uxr-audit-2026-10.WAL-11', 'uxr-audit-2026-10', 'WAL-11', 'Wallet', 'Wallet', 'Purchase list highlighted row', 'Visual', 'Both', 1, '**Prod:** the first purchase row has a green border and mint fill, with no explanation. **Figma:** the purchases list has no highlighted rows. Green highlight appears only in the Transactions list, on earned-points rows (3196:35382, 8576:29565).', 'ar/61, en/61', '3196:36017, 8585:47345, 3196:35382', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 73, 'audit'),
  ('uxr-audit-2026-10.WAL-12', 'uxr-audit-2026-10', 'WAL-12', 'Wallet', 'Wallet', 'AR date and time format in the list', 'Copy', 'AR', 2, '**Figma:** headers like "20 يوليو" (no year) and times like "08:30م", Western digits with a ص/م marker. **Prod:** header "١٦ يوليو ٢٠٢٦" and times "١:٣٠" and "١١:١٤", Eastern Arabic digits with no ص/م marker, so 12-hour times are ambiguous. The prod details screen shows the same purchase as "01:30 م" in Western digits.', 'ar/61', '3196:36017', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 74, 'audit'),
  ('uxr-audit-2026-10.WAL-13', 'uxr-audit-2026-10', 'WAL-13', 'Wallet', 'Wallet', 'EN date and time format in the list', 'Copy', 'EN', 1, '**Prod list:** "13:30" (24-hour) with header "Jul 16, 2026". **Figma:** 12-hour times ("AM 8:30" in 8585:47345, "08:30PM" in 2200:33446) with headers like "20 July" or "Today". **Prod details:** "16 Jul 2026, 01:30 PM". That is three formats for one timestamp.', 'en/61', '8585:47345, 2200:33446', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 75, 'audit'),
  ('uxr-audit-2026-10.WAL-14', 'uxr-audit-2026-10', 'WAL-14', 'Wallet', 'Wallet', 'EN purchase titles not localised', 'Data', 'EN', 2, '**Prod EN list:** Arabic titles ("خصم 20 % على إجمالي الفاتورة") inside the English UI. **Prod EN details:** the same item reads "20% discount on total bill", so the list uses an untranslated field. **Figma EN list:** English titles.', 'en/61', '8585:47345', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 76, 'audit'),
  ('uxr-audit-2026-10.WAL-15', 'uxr-audit-2026-10', 'WAL-15', 'Wallet', 'Purchase details', 'Offer validity date', 'Missing in prod', 'Both', 3, '**Figma newest:** validity under the title ("ينتهي في: 25.07.2026" / "Valid until 25 July 2026"). **Older Account version (2585:28012):** "Valid until" under the camera box. **Prod:** no validity or expiry date on the details screen, the Wallet list or My Items (only a "Valid / صالح" badge). After buying an offer, the user cannot see when it expires.', 'ar/62, ar/63, en/62, ar/61, ar/79', '8903:6857, 8902:15726, 2585:28012', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 77, 'audit'),
  ('uxr-audit-2026-10.WAL-16', 'uxr-audit-2026-10', 'WAL-16', 'Wallet', 'Purchase details', 'Camera box copy', 'Copy', 'Both', 2, '**Figma AR:** "فعّل الكاميرا لمسح رمز المتجر." with button "تفعيل الكاميرا". **Figma EN:** "Enable camera access to scan the store''s QR code." with button "Enable Camera". **Prod AR:** "فعّل الكاميرا" with button "تفعيل". **Prod EN:** "Enable camera access" with button "Activate". The reason (scanning the store''s QR code) is gone, and "Activate" / "تفعيل" reads as activating the offer, not the camera.', 'ar/62, ar/63, en/62', '8903:6857, 8902:15726', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 78, 'audit'),
  ('uxr-audit-2026-10.WAL-17', 'uxr-audit-2026-10', 'WAL-17', 'Wallet', 'Purchase details', 'Section title and status badge', 'Copy', 'Both', 1, '**Section title:** Figma "استخدم العرض الآن" / "Use the Offer"; prod "استخدم العرض الآن وامسح الكود" / "Use the offer now and scan the code". **Badge:** Figma "ساري" / "Active"; prod "صالح" / "Valid". Status words vary across Figma and prod: ساري/منتهي, صالح, Active/Expired/Finished, Valid.', 'ar/62, en/62', '8903:6857, 8902:15726', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 79, 'audit'),
  ('uxr-audit-2026-10.WAL-18', 'uxr-audit-2026-10', 'WAL-18', 'Wallet', 'Purchase details', 'Transaction number', 'Data', 'Both', 2, '**Figma:** a short reference ("jkdDko"). **Prod:** the raw 36-character UUID "daf40edf-4328-41a1-83e7-0226ee0ca6e3". In AR it is squeezed into small text; in EN it is cut to "daf40edf-4328-41a1-83e7-0226…", so the full number cannot be read. There is no copy action, which makes it hard to quote to support.', 'ar/62, ar/63, en/62', '8903:6857, 8902:15726', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 80, 'audit'),
  ('uxr-audit-2026-10.WAL-19', 'uxr-audit-2026-10', 'WAL-19', 'Wallet', 'Purchase details', 'EN summary copy', 'Copy', 'EN', 1, '**Heading:** "Transaction Summary" (Title Case) where Figma has "Transaction summary". **Type:** "Buying offer" where Figma has "Purchase Offer". **Date:** "16 Jul 2026, 01:30 PM" where Figma has "July 20, 2025, 8:30 PM".', 'en/62', '8902:15726', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 81, 'audit'),
  ('uxr-audit-2026-10.WAL-20', 'uxr-audit-2026-10', 'WAL-20', 'Wallet', 'Purchase details', 'Help row copy', 'Copy', 'Both', 1, '**AR:** Figma newest "واجهت مشكلة؟ / تواصل معنا وسنساعدك."; prod "واجهتك مشكلة؟ / تواصل معنا وابشر بالحل". **EN:** Figma newest "Did you encounter a problem? / Contact us and get to the solution."; prod "Need help? / Let us know and we''ll help right away". Prod EN follows the older Account-page copy ("Need help? Contact us and we''ll help you right away.").', 'ar/62, ar/63, en/62', '8903:6857, 8902:15726, 2585:28012', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 82, 'audit'),
  ('uxr-audit-2026-10.WAL-21', 'uxr-audit-2026-10', 'WAL-21', 'Wallet', 'Purchase details', 'Bottom CTA label', 'Copy', 'AR', 1, 'Figma "طريقة استخدام العرض"; prod "كيف تستخدم العرض". The EN CTA is cut off at the bottom of en/62 and could not be compared.', 'ar/63', '8903:6857', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 83, 'audit'),
  ('uxr-audit-2026-10.WAL-22', 'uxr-audit-2026-10', 'WAL-22', 'Wallet', 'Purchase details', 'Camera illustration', 'Visual', 'Both', 1, '**Figma:** a lavender and blue-grey camera on a lavender blob, matching the design palette. **Prod:** a flat mid-grey camera on a grey blob.', 'ar/62, ar/63, en/62', '8903:6857, 8902:15726', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 84, 'audit'),
  ('uxr-audit-2026-10.WAL-23', 'uxr-audit-2026-10', 'WAL-23', 'Wallet', 'My Items (benefits used)', 'Page title and naming', 'Copy', 'Both', 2, '**Figma title:** "مشترياتي" / "My Purchases". **Prod title:** "المزايا الي استفدت منها", with colloquial "الي". Per the field notes, the EN account menu calls it "My Items". The Wallet tab calls the same list "المشتريات" / "Purchases", so one list has three names.', 'ar/79', '84:21364 (AR), 2200:33446 (EN)', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 85, 'audit'),
  ('uxr-audit-2026-10.WAL-24', 'uxr-audit-2026-10', 'WAL-24', 'Wallet', 'My Items (benefits used)', 'Chips', 'Copy', 'AR', 1, '**Figma:** "الأقدم ⌄" (a filled sort chip that shows the selected order), "العروض", "القسائم الشرائية". **Prod:** "ترتيب حسب ⌄" (an outline chip that shows no selected order), "العروض" (selected), and "القسائم" (shortened). The sort label also differs from the Wallet''s "رتبها".', 'ar/79', '84:21364', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 86, 'audit'),
  ('uxr-audit-2026-10.WAL-25', 'uxr-audit-2026-10', 'WAL-25', 'Wallet', 'My Items (benefits used)', 'Time format', 'Copy', 'AR', 1, 'Figma "08:30م". Prod "01:30PM" and "11:14AM", Latin AM/PM inside the Arabic UI. These differ from the Wallet list for the same items ("١:٣٠", see WAL-12).', 'ar/79', '84:21364', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 87, 'audit'),
  ('uxr-audit-2026-10.WAL-26', 'uxr-audit-2026-10', 'WAL-26', 'Wallet', 'Wallet', 'Balance card gradient', 'Visual', 'Both', 1, '**Figma:** the card goes from dark green to green, with an olive/khaki tint in the lower-right corner. **Prod:** dark green to brighter green, with no visible olive tint.', 'ar/60, en/60', '4195:32126, 8576:33799', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 88, 'audit'),
  ('uxr-audit-2026-10.ACC-01', 'uxr-audit-2026-10', 'ACC-01', 'Account & settings', 'Account tab', 'Profile card', 'Data', 'Both', 2, 'The role line shows the raw lowercase English value "employee" in both languages. Figma shows a localized label: "حساب موظف" (AR) / "Regular user" (EN).', 'ar/70, en/70', '2018:7422, 84:19647, 2200:22751, 2200:20708', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 89, 'audit'),
  ('uxr-audit-2026-10.ACC-02', 'uxr-audit-2026-10', 'ACC-02', 'Account & settings', 'Account tab', 'Profile card', 'Copy', 'EN', 1, 'Prod abbreviates the company label to "Current Co."; Figma uses "Current Company".', 'en/70', '2200:22751, 2200:23257', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 90, 'audit'),
  ('uxr-audit-2026-10.ACC-03', 'uxr-audit-2026-10', 'ACC-03', 'Account & settings', 'Account tab', 'Profile card chips', 'Component', 'Both', 2, 'The user has 1 company and no invitations, but prod shows the multi-company card with an envelope chip "0+" (AR "+0") and a building chip "1". Figma has a separate "Single profile" card variant without chips for this case. A zero count is shown as "0+".', 'ar/70, en/70, en/93', '2200:23257 (Multiple profiles), 2200:23300 (Single profile), 84:20343', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 91, 'audit'),
  ('uxr-audit-2026-10.ACC-04', 'uxr-audit-2026-10', 'ACC-04', 'Account & settings', 'Account tab', 'Profile card chips → destinations', 'Navigation', 'Both', 2, 'In prod, the envelope chip opens My Family (en/94) and the building chip opens the company sheet (en/93). In Figma, the envelope chip''s count ("2+") equals "Pending Invitations 2" in My Company Accounts (Co - 1), so it appears to stand for pending company invitations. Figma reaches family management from the My Family card (gear icon in Account - 2). This is inferred from the matching counts; Figma has no prototype link to confirm it.', 'en/70, en/93, en/94', '2200:22751, 2200:24725 (Co - 1), 2200:20708', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 92, 'audit'),
  ('uxr-audit-2026-10.ACC-05', 'uxr-audit-2026-10', 'ACC-05', 'Account & settings', 'Account tab', 'My Family card (empty)', 'Copy', 'Both', 1, 'AR prod: "قم بدعوة افراد عائلتك / واستمتع بمزايا عائلية حصرية كثيرة". AR Figma: "أضف أفراد عائلتك / وادعهم للاستفادة من المزايا الحصرية للعائلة.". EN prod: "Invite your family members". EN Figma: "Invite a Family Member" (the subtitle matches).', 'ar/70, en/70', '2018:7422, 2200:22751', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 93, 'audit'),
  ('uxr-audit-2026-10.ACC-06', 'uxr-audit-2026-10', 'ACC-06', 'Account & settings', 'Account tab', 'Section headings', 'Copy', 'Both', 2, 'The first group is titled "رأس مالي" ("my capital") in AR prod and "Things I own" in EN prod. Figma: "رصيدي المالي" / "My Benefits". The second AR group is "ضبط تجربتك على ذوقك" in prod vs "خصّص تجربتك" in Figma (EN "Personalization" matches).', 'ar/70–71, en/70–71', '2018:7422, 2200:22751', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 94, 'audit'),
  ('uxr-audit-2026-10.ACC-07', 'uxr-audit-2026-10', 'ACC-07', 'Account & settings', 'Account tab', 'Benefits group', 'Missing in prod', 'Both', 2, 'Prod has no "الفواتير / Invoice Rewards — Points collected from invoices" row; it lists only My Items and Gifts.', 'ar/70, en/70', '2018:7422, 2200:22751', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 95, 'audit'),
  ('uxr-audit-2026-10.ACC-08', 'uxr-audit-2026-10', 'ACC-08', 'Account & settings', 'Account tab', 'Personalization group', 'Missing in prod', 'Both', 1, 'Prod has no "مظهر التطبيق / App Appearance — Change the look of the app" row. No appearance screen was found on this Figma page either.', 'ar/71, en/71', '2018:7422, 2200:22751', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 96, 'audit'),
  ('uxr-audit-2026-10.ACC-09', 'uxr-audit-2026-10', 'ACC-09', 'Account & settings', 'Account tab', 'Row labels & subtitles', 'Copy', 'Both', 1, 'Labels and subtitles diverge (prod vs Figma):<br>• Benefits row: "المزايا الي استفدت منها / قسائم وعروض" vs "المزايا التي استفدت منها / استعرض قيمة التوفير من العروض والخصومات."; EN "My Items" vs "Offers & Vouchers".<br>• Gifts subtitle: "قسائم الهدايا / Gifts vouchers" vs "استعرض الهدايا التي استلمتها وأرسلتها. / Gifts you''ve sent and received".<br>• Interests subtitle (AR): "اختر فئات القسائم والعروض" vs "تخصيص العروض والقسائم".<br>• Favorites subtitle: "العلامات اللي أتابعها / Brands I follow" vs "العروض والمتاجر المحفوظة / View your favorite stores".<br>• FAQs subtitle (AR): "أسئلة متكررة" vs "إجابات عن أكثر الأسئلة شيوعًا".<br>• Contact row: "ارسل لنا ونضبطك / نخدمك باللي تحتاج" vs "تواصل معنا / نحن هنا لمساعدتك"; EN subtitle "We''ll serve you with what you need" vs "Get in touch with our support team".<br>• Chat row (EN): "Instant chat" vs "Live Chat".', 'ar/70–71, en/70–71', '2018:7422, 2200:22751', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 97, 'audit'),
  ('uxr-audit-2026-10.ACC-10', 'uxr-audit-2026-10', 'ACC-10', 'Account & settings', 'Account tab', 'Help group structure', 'Missing in Figma', 'AR', 1, 'AR prod''s Help group is FAQs, Contact, "محادثة فورية" (live chat), and Feedback. The AR Figma Account frames have no live-chat row; they show two feedback rows instead ("أرسل ملاحظاتك" and "اقترح فكرة"). Prod matches the EN Figma structure, so the AR design is out of date.', 'ar/71', '2018:7422, 84:19647, 2200:22751', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 98, 'audit'),
  ('uxr-audit-2026-10.ACC-11', 'uxr-audit-2026-10', 'ACC-11', 'Account & settings', 'Account tab', 'Feedback entry', 'Copy', 'Both', 2, 'The entry is labelled "شفت شي ما عجبك؟" ("saw something you didn''t like?") in AR and "Feedback" in EN. It opens the idea form "ساعدنا نتطور". Figma labels it "اقترح فكرة / ساعدنا على تطوير تجربتك" (AR) and "Share an Idea" (EN). Prod''s complaint framing doesn''t match the suggestion form it opens.', 'ar/71, en/71, ar/78', '2018:7422, 2200:22751, 84:12305', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 99, 'audit'),
  ('uxr-audit-2026-10.ACC-12', 'uxr-audit-2026-10', 'ACC-12', 'Account & settings', 'Account tab / FAQs', 'FAQs row & FAQ page title', 'Copy', 'AR', 1, 'Prod writes "الاسئلة الشائعة" without the hamza; Figma has "الأسئلة الشائعة".', 'ar/71, ar/74', '2018:7422, 84:10798', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 100, 'audit'),
  ('uxr-audit-2026-10.ACC-13', 'uxr-audit-2026-10', 'ACC-13', 'Account & settings', 'Account tab', 'Favorites row icon', 'Visual', 'AR', 1, 'Prod uses a bell icon for Favorites. AR Figma uses a heart, which matches the hearts on the Favorites page; EN Figma also uses a bell. Figma itself is inconsistent.', 'ar/71, en/71', '2018:7422, 2200:22751, 153:37130', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 101, 'audit'),
  ('uxr-audit-2026-10.ACC-14', 'uxr-audit-2026-10', 'ACC-14', 'Account & settings', 'Company accounts', 'My Company Accounts', 'Navigation', 'EN', 1, 'Prod shows company switching as a bottom sheet: drag handle, X, and the Account screen and nav bar dimmed behind it. Figma designs it as a full-screen page with X at the top and no nav bar.', 'en/93', '2200:24725, 2200:25362, 88:11527, 2016:20860', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 102, 'audit'),
  ('uxr-audit-2026-10.ACC-15', 'uxr-audit-2026-10', 'ACC-15', 'Account & settings', 'Company accounts', 'My Company Accounts', 'Copy', 'EN', 1, 'Prod: "Select the company account to switch to. Each company has its own points and rewards." Figma: "Choose a company account. Each account has separate points and rewards." The CTA reads "Change Company" in prod vs "Switch Company" in Figma.', 'en/93', '2200:24725', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 103, 'audit'),
  ('uxr-audit-2026-10.ACC-16', 'uxr-audit-2026-10', 'ACC-16', 'Account & settings', 'Company accounts', 'Single-company state', 'Missing in Figma', 'EN', 1, 'Prod shows one company card and a permanently disabled "Change Company" button. Figma only covers the multi-company case with pending invitations; there is no single-company or no-invitations state.', 'en/93', '2200:24725, 2200:25362', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 104, 'audit'),
  ('uxr-audit-2026-10.ACC-17', 'uxr-audit-2026-10', 'ACC-17', 'Account & settings', 'My Family', 'My Family list', 'State', 'EN', 2, 'Prod shows a blank white page with only the bottom "Invite new Member" button: no illustration, explanation, or invite limit. Figma has only populated states (Fam 1–5 / AR family), so no empty state is designed.', 'en/94', '2200:28202, 2200:30492, 2218:22076, 2018:8298', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 105, 'audit'),
  ('uxr-audit-2026-10.ACC-18', 'uxr-audit-2026-10', 'ACC-18', 'Account & settings', 'My Family', 'My Family list', 'Copy', 'EN', 1, 'The button reads "Invite new Member" (odd casing). Figma EN: "Invite a Family Member"; Figma AR: "دعوة فرد جديد".', 'en/94', '2200:28202, 2018:8298', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 106, 'audit'),
  ('uxr-audit-2026-10.ACC-19', 'uxr-audit-2026-10', 'ACC-19', 'Account & settings', 'Invite member', 'Invite family member form', 'Copy', 'AR', 1, 'Prod vs Figma:<br>• Title: "دعوة فرد من العائلة" vs "دعوة فرد عائلة".<br>• Benefit cards: "تسوق القسائم كهدية / تجميع هدايا أكبر / تحويل النقاط فوراً" vs "إهداء القسائم لأفراد العائلة / جمع النقاط في رصيد مشترك / تحويل النقاط بين أفراد العائلة".<br>• Labels: "رقم جوال فرد العائلة" vs "أدخل رقم جوال فرد العائلة"; "اسم فرد العائلة" vs "أدخل الاسم الكامل".<br>• Placeholder: "مثال: أحمد خالد العايد" vs "مثل, نواف عباد".<br>• CTA: "أرسل الدعوة" vs "إرسال الدعوة".', 'ar/81', '2018:9265, 2018:9832', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 107, 'audit'),
  ('uxr-audit-2026-10.ACC-20', 'uxr-audit-2026-10', 'ACC-20', 'Account & settings', 'Invite member', 'Invite family member form', 'Copy', 'EN', 1, 'Prod vs Figma:<br>• Phone label: "Family member''s phone number" vs "Phone Number"; placeholder "5xx xxx xxx" vs "Phone number".<br>• Name label: "Family member name" vs "Family Member''s Name"; placeholder "Ex. Ahmed Khaled alayed" (casing) vs "Enter full name".<br>• "The Relationship" vs "Relationship".<br>• Benefit card: "Accumulated points for bigger gifts" vs "Combine points for bigger rewards".', 'en/81', '2200:29703, 2200:30284', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 108, 'audit'),
  ('uxr-audit-2026-10.ACC-21', 'uxr-audit-2026-10', 'ACC-21', 'Account & settings', 'Interests', 'Interests', 'Data', 'AR', 2, 'Prod lists fine-grained sub-categories ("كافيهات", "قهوة مختصة", "أجهزة القهوة", "مشروبات", "عصائر", "مياه", "آسيوية", "وجبة الفطور", "طعام عربي" …) in a long scrolling grid. Figma shows 12 top-level categories that fit on one screen (الأكل والمشروبات, الأزياء, السفر والسياحة, الترفيه, اللياقة, المنزل, العناية الشخصية, السيارات, الخدمات العامة, الرعاية الصحية, الورود والهدايا, العطور).', 'ar/72', '84:11076, 84:11231, 2201:20262', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 109, 'audit'),
  ('uxr-audit-2026-10.ACC-22', 'uxr-audit-2026-10', 'ACC-22', 'Account & settings', 'Interests', 'Interests', 'Visual', 'AR', 2, 'Most prod tiles have no icon (or a faint one) or a generic △○□ placeholder icon. Every Figma tile has its own line icon. The selected style (green border) matches.', 'ar/72', '84:11076', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 110, 'audit'),
  ('uxr-audit-2026-10.ACC-23', 'uxr-audit-2026-10', 'ACC-23', 'Account & settings', 'Interests', 'Interests', 'Copy', 'AR', 1, 'Title: "اهتماماتي" vs "الإهتمامات". Subtitle: "عشان نعرض لك المزايا الي تناسب اهتماماتك وذوقك" vs "اختر اهتماماتك لنقدّم لك عروضًا ومزايا تناسبك.". CTA: "تم" vs "حفظ".', 'ar/72', '84:11076', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 111, 'audit'),
  ('uxr-audit-2026-10.ACC-24', 'uxr-audit-2026-10', 'ACC-24', 'Account & settings', 'Favorites', 'Favorites', 'State', 'AR', 2, 'Prod shows a search field, an empty area, and a disabled "حفظ" button, with no empty-state message or illustration. Figma only shows the populated grid (store cards with heart toggles and Offers/Vouchers/Cashback tags); no empty state is designed.', 'ar/73', '153:37130, 84:10915, 2201:21208', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 112, 'audit'),
  ('uxr-audit-2026-10.ACC-25', 'uxr-audit-2026-10', 'ACC-25', 'Account & settings', 'Favorites', 'Favorites', 'Copy', 'AR', 1, 'The search placeholder reads "ابحث عن علامة تجارية .." in prod vs "ابحث عن متجر" in Figma.', 'ar/73', '153:37130', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 113, 'audit'),
  ('uxr-audit-2026-10.ACC-26', 'uxr-audit-2026-10', 'ACC-26', 'Account & settings', 'Contact us', 'Contact us', 'Copy', 'AR', 2, 'The social rows are in English ("Follow us on Instagram", "Follow us on X", "Follow us on Tiktok", "Follow us on Facebook") inside the Arabic screen. AR Figma uses Arabic labels ("تابعنا على إنستغرام", "تابعنا على منصة إكس" …).', 'ar/76', '84:11799, 2201:21954', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 114, 'audit'),
  ('uxr-audit-2026-10.ACC-27', 'uxr-audit-2026-10', 'ACC-27', 'Account & settings', 'Contact us', 'Contact us', 'Copy', 'AR', 1, 'The intro is the "data on the website" message ("إذا كان لديك أي استفسارات حول بياناتك على الموقع…"). That is a translation of the EN Figma intro, not the AR Figma intro "نسعد بخدمتك والإجابة عن استفساراتك…". Section titles read "تفاصيل التواصل" / "روابط التواصل" vs "تواصل معنا" / "منصات التواصل". The support row reads "تحتاج مساعدة؟ / تواصل معنا في أي وقت" vs "الدعم والمساعدة / أرسل استفسارك، وسنرد عليك في أقرب وقت.".', 'ar/76', '84:11799, 2201:21954', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 115, 'audit'),
  ('uxr-audit-2026-10.ACC-28', 'uxr-audit-2026-10', 'ACC-28', 'Account & settings', 'Contact us / Settings', 'Social platform list', 'Data', 'Both', 1, 'Prod lists Instagram, X, TikTok, Facebook and LinkedIn. AR Figma (Contact us and Settings) lists Instagram, X, Snapchat, TikTok and Telegram; EN Figma Contact us lists Facebook, Instagram, LinkedIn, X and TikTok.', 'ar/76, ar/83, en/83', '84:11799, 2201:21954, 153:34806, 2201:29945', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 116, 'audit'),
  ('uxr-audit-2026-10.ACC-29', 'uxr-audit-2026-10', 'ACC-29', 'Account & settings', 'Live chat', 'Live chat', 'Missing in Figma', 'Both', 2, 'Figma designs the entry points (the Live Chat row and the "Need help?" card) but no chat screen. Prod opens a third-party Freshworks widget.', 'ar/77', '2200:22751 (Live Chat row), 84:10689 / 2201:21744 ("Need help? Chat with our support team")', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 117, 'audit'),
  ('uxr-audit-2026-10.ACC-30', 'uxr-audit-2026-10', 'ACC-30', 'Account & settings', 'Live chat', 'Live chat', 'RTL/LTR', 'AR', 2, 'In the Arabic app, the chat widget is entirely in English and left-to-right: "Customer Support", "Typically replies within a minute", "Hello, good to have you here. How can I help you?", "Type a message". Only the agent avatar carries the WalaPlus mark; the header and controls are unbranded (black header, generic pattern background, blue send icon).', 'ar/77', '—', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 118, 'audit'),
  ('uxr-audit-2026-10.ACC-31', 'uxr-audit-2026-10', 'ACC-31', 'Account & settings', 'Suggestion form', 'Suggest anything', 'Copy', 'AR', 2, 'The description placeholder is sample filler: "هنا بعض النصوص العربية لوصف ما يعتقده المستخدم حول التطبيق." It is a variant of the sample text in Figma''s filled-state frame 84:12316 ("كتب هنا بعض النصوص العربية…"). Figma''s empty-state placeholder is "اشرح فكرتك بالتفصيل...".', 'ar/78', '84:12305, 84:12316', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 119, 'audit'),
  ('uxr-audit-2026-10.ACC-32', 'uxr-audit-2026-10', 'ACC-32', 'Account & settings', 'Suggestion form', 'Suggest anything', 'Copy', 'AR', 1, 'Field label: "الفكرة" vs "عنوان الفكرة". Title placeholder: "اكتب عنوان للاقتراح" vs "اكتب عنوانًا مختصرًا للفكرة". CTA: "أرسل" vs "إرسال الاقتراح".', 'ar/78', '84:12305', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 120, 'audit'),
  ('uxr-audit-2026-10.ACC-33', 'uxr-audit-2026-10', 'ACC-33', 'Account & settings', 'My purchases (benefits used)', 'Benefits used list', 'Copy', 'AR', 1, 'The screen title is "المزايا الي استفدت منها" vs Figma "مشترياتي". The sort chip reads "ترتيب حسب"; Figma shows the active sort value ("الأقدم"). The status pill reads "صالح" vs "ساري".', 'ar/79', '84:21364, 84:22010, 2200:33446', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 121, 'audit'),
  ('uxr-audit-2026-10.ACC-34', 'uxr-audit-2026-10', 'ACC-34', 'Account & settings', 'My purchases (benefits used)', 'Benefits used list', 'Data', 'AR', 2, 'Rows show the offer text ("خصم 20 % على إجمالي الفاتورة") and a small logo but no brand name. Figma rows read "عرض من <brand>" (e.g. "عرض من نمق").', 'ar/79', '84:21364, 2200:33446', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 122, 'audit'),
  ('uxr-audit-2026-10.ACC-35', 'uxr-audit-2026-10', 'ACC-35', 'Account & settings', 'My purchases (benefits used)', 'Benefits used list', 'Copy', 'AR', 1, 'Times use Latin AM/PM ("01:30PM", "11:14AM"); Figma uses "08:30م". The date header uses Eastern Arabic digits ("١٦ يوليو") while Figma uses Western digits ("28 يونيه").', 'ar/79', '84:21364', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 123, 'audit'),
  ('uxr-audit-2026-10.ACC-36', 'uxr-audit-2026-10', 'ACC-36', 'Account & settings', 'Gifts', 'Gifts – empty', 'Visual', 'AR', 1, 'The "إهداء قسيمة" CTA is a wide button (about 85% of the screen) right under the text. Figma uses a compact, centred button placed lower. Illustration and copy match exactly.', 'ar/80', '84:11690, 2201:18708', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 124, 'audit'),
  ('uxr-audit-2026-10.ACC-37', 'uxr-audit-2026-10', 'ACC-37', 'Account & settings', 'Settings', 'Settings', 'Missing in prod', 'Both', 1, 'Prod has no "بطاقات الدفع / Payment cards" row, which is in both current Figma Settings frames.', 'ar/82, en/82', '153:34806, 2201:29945, 272:49766', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 125, 'audit'),
  ('uxr-audit-2026-10.ACC-38', 'uxr-audit-2026-10', 'ACC-38', 'Account & settings', 'Settings', 'Settings › Security', 'Missing in Figma', 'Both', 2, 'Prod''s Security group has a "تغيير الرقم السري / Change PIN code" row. The Figma Security group has only Biometric Login, and this page has no change-PIN flow.', 'ar/82, en/82, ar/88', '153:34806, 2201:29945', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 126, 'audit'),
  ('uxr-audit-2026-10.ACC-39', 'uxr-audit-2026-10', 'ACC-39', 'Account & settings', 'Settings', 'Settings › Social links', 'Copy', 'Both', 1, 'Prod shows bare lowercase brand names ("instagram", "x", "tiktok", "facebook", "linkedin") under "روابط التواصل / Social links". Figma uses "تابعنا على إنستغرام…" / "Follow us on Instagram…" under "منصات التواصل / Social Media". Prod is also inconsistent with its own Contact us labels ("Follow us on Instagram").', 'ar/83, en/83', '153:34806, 2201:29945', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 127, 'audit'),
  ('uxr-audit-2026-10.ACC-40', 'uxr-audit-2026-10', 'ACC-40', 'Account & settings', 'Settings', 'Settings', 'Copy', 'AR', 1, 'Prod vs Figma:<br>• "المعلومات الأساسية" vs "إعدادات الحساب".<br>• "المعلومات الشخصية" vs "البيانات الشخصية" (prod''s own page title is "البيانات الشخصية").<br>• "تغيير اللغة" vs "اللغة".<br>• "الأمان" vs "الحماية".<br>• "تفعيل البصمة" vs "تسجيل الدخول بالبصمة".<br>• "الشروط والخصوصية" vs "الشروط والأحكام وسياسة الخصوصية".<br>• "قيّم التطبيق" vs "قيّم تجربتك".', 'ar/82–83', '153:34806', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 128, 'audit'),
  ('uxr-audit-2026-10.ACC-41', 'uxr-audit-2026-10', 'ACC-41', 'Account & settings', 'Settings', 'Settings', 'Copy', 'EN', 1, 'Prod vs Figma: "Personal info" vs "Personal Information"; "Change language" vs "Language"; "Activate biometrics" vs "Biometric Login"; "About WalaPlus" vs "WalaPlus"; "Terms & Privacy" vs "Terms & Privacy Policy"; "Rate the App" vs "Rate Your Experience"; "Logout" vs "Log Out".', 'en/82–83', '2201:29945', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 129, 'audit'),
  ('uxr-audit-2026-10.ACC-42', 'uxr-audit-2026-10', 'ACC-42', 'Account & settings', 'Personal info', 'Personal info', 'Missing in prod', 'Both', 2, 'Prod has no "رقم العميل / Customer Number" field or its "نسخ / Copy" button.', 'ar/84, en/84', '153:35317, 2201:30717', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 130, 'audit'),
  ('uxr-audit-2026-10.ACC-43', 'uxr-audit-2026-10', 'ACC-43', 'Account & settings', 'Personal info', 'Personal info', 'Data', 'Both', 2, 'The mobile value "966556677889" repeats the country code that the "+966" selector already shows. Figma shows "+966" plus the national number only.', 'ar/84, en/84', '153:35317, 2201:30717', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 131, 'audit'),
  ('uxr-audit-2026-10.ACC-44', 'uxr-audit-2026-10', 'ACC-44', 'Account & settings', 'Personal info', 'Personal info', 'Copy', 'Both', 1, 'AR labels: "اسمك الكريم", "ايميلك" vs "الاسم الكامل", "البريد الإلكتروني". EN title: "Personal Info" vs "Personal Information"; EN label: "Email" vs "Email Address". The date format is "01/12/1992" vs AR Figma "02.08.1997".', 'ar/84, en/84', '153:35317, 2201:30717, 2201:30833', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 132, 'audit'),
  ('uxr-audit-2026-10.ACC-45', 'uxr-audit-2026-10', 'ACC-45', 'Account & settings', 'Personal info', 'Phone field', 'RTL/LTR', 'AR', 1, 'Prod''s phone field has a country-code dropdown (flag, "+966", chevron). In AR it sits at the right (start) edge and renders as "966+". Figma shows a static flag + "+966" segment on the left in both languages, with no chevron.', 'ar/84, en/84', '153:35317, 2201:30717', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 133, 'audit'),
  ('uxr-audit-2026-10.ACC-46', 'uxr-audit-2026-10', 'ACC-46', 'Account & settings', 'About', 'About WalaPlus', 'Copy', 'AR', 1, 'The body text differs. Prod: "ولاء بلس هي منصة مزايا الموظفين الرائدة في المملكة العربية السعودية…". Figma: "ولاء بلس منظومة متكاملة تقدّم حلولًا مخصّصة للجهات والمنشآت…". The layout (logo card + paragraph) matches.', 'ar/85', '153:36774, 2203:20274', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 134, 'audit'),
  ('uxr-audit-2026-10.ACC-47', 'uxr-audit-2026-10', 'ACC-47', 'Account & settings', 'Terms & privacy', 'Terms & Privacy', 'Copy', 'AR', 1, 'The title reads "الشروط وسياسة الخصوصية" vs Figma "الشروط والأحكام وسياسة الخصوصية". The Settings row uses a third wording, "الشروط والخصوصية".', 'ar/86', '153:36921, 2203:20112', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 135, 'audit'),
  ('uxr-audit-2026-10.ACC-48', 'uxr-audit-2026-10', 'ACC-48', 'Account & settings', 'Rate app', 'Rate experience sheet', 'Copy', 'AR', 1, 'Prod vs Figma:<br>• Label: "رهيب!" vs "رهيبة!" (Figma agrees with the feminine تجربة).<br>• Title: "وش رأيك في تجربتك مع ولاء بلس؟" vs "وش رأيك بتجربتك في تطبيق ولاء بلس؟".<br>• Placeholder: "إذا كان لديك أي تعليقات..." vs "عندك ملاحظات؟ شاركنا رأيك...".<br>• CTA: "إرسال" vs "إرسال التقييم".', 'ar/87', '2016:21587, 2202:33249–2202:33326', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 136, 'audit'),
  ('uxr-audit-2026-10.ACC-49', 'uxr-audit-2026-10', 'ACC-49', 'Account & settings', 'Rate app', 'Rate experience sheet', 'Component', 'AR', 1, 'Prod''s title is plain grey text, without Figma''s bold "ولاء بلس؟" line and dashed divider. Prod''s slider has no stop ticks; Figma uses a 3-stop slider with tick marks. Prod''s feedback field is a bordered input box; Figma uses a borderless icon + text line. Prod opens at the top value ("رهيب!"); Figma''s frame order starts at "ما أعجبتني", though the default is not annotated.', 'ar/87', '2016:21587', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 137, 'audit'),
  ('uxr-audit-2026-10.ACC-50', 'uxr-audit-2026-10', 'ACC-50', 'Account & settings', 'Change PIN', 'Change-PIN OTP', 'Copy', 'AR', 2, 'The change-PIN OTP reuses the login screen copy "هلا بيك مرة ثانية!" ("welcome back") and "عطنا الرمز". The Figma OTP frames in Settings have context titles ("رمز التحقق" + "تحقّق من…" / "Verify Your Phone Number").', 'ar/88', '2016:21861, 153:35707, 2201:32157', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 138, 'audit'),
  ('uxr-audit-2026-10.ACC-51', 'uxr-audit-2026-10', 'ACC-51', 'Account & settings', 'Change PIN', 'Change-PIN OTP', 'RTL/LTR', 'AR', 1, 'The masked phone number renders scrambled, with a dot on the wrong side ("+966 5 ••••• 889•"). Figma shows the number intact ("+96660550225").', 'ar/88', '2016:21861', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 139, 'audit'),
  ('uxr-audit-2026-10.ACC-52', 'uxr-audit-2026-10', 'ACC-52', 'Account & settings', 'QR scanner', 'Camera priming sheet', 'Missing in Figma', 'AR', 1, 'Prod''s camera-permission bottom sheet (camera illustration, "بس افتح الكاميرا ...", "اسمح بالكاميرا" / "خلها بعدين") has no Figma counterpart. Figma has location-priming sheets (Market 4855:24026 / 8609:87503) and an inline "تفعيل الكاميرا" card in Wallet transaction details (8903:6857), but no camera priming sheet.', 'ar/89', '7631:18650, 2585:28277, 8903:6857, 4855:24026', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 140, 'audit'),
  ('uxr-audit-2026-10.ACC-53', 'uxr-audit-2026-10', 'ACC-53', 'Account & settings', 'QR scanner', 'Scanner screen (behind sheet)', 'Copy', 'AR', 2, 'Prod title/subtitle: "امسح الكود وفالك العرض" / "فضلاً اطلب من المتجر مسح كود ولاء بلس" ("ask the store to scan the WalaPlus code"). Figma: "امسح الرمز وفعّل العرض" / "اطلب رمز ولاء بلس من المتجر، ثم امسحه لتفعيل العرض.". Prod''s instruction reverses who scans whom.', 'ar/89', '7631:18650, 2585:28277', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 141, 'audit'),
  ('uxr-audit-2026-10.ACC-54', 'uxr-audit-2026-10', 'ACC-54', 'Account & settings', 'QR scanner', 'Scanner + priming sheet', 'Visual', 'AR', 1, 'Two close (X) buttons are visible at once: the scanner''s X at top-left and the sheet''s X. The Figma scanner has a single X.', 'ar/89', '7631:18650', 'open', 'UX audit', '2026-10-27T09:00:00Z', '2026-10-27T09:00:00Z', 142, 'audit')
